const speaker = ChatMessage.getSpeaker();
const actor = game.actors.get(speaker.actor);

if (!actor) {
  ui.notifications.warn("Select a token or assign a default character.");
  return;
}

const res = actor.system.resources?.secondary;
if (!res) {
  ui.notifications.error("This actor has no secondary resource slot.");
  return;
}

// Roll 1d4+1
const roll = await new Roll("1d4+1").evaluate();

// Update the pool
const oldVal = res.value ?? 0;
const newVal = oldVal + roll.total;
await actor.update({ "system.resources.secondary.value": newVal });

// Post to chat with the roll
const content = `
  <div class="dnd5e chat-card">
    <header class="card-header flexrow">
      <img src="icons/svg/d20-grey.svg" width="36" height="36"/>
      <h3>Luck Roll</h3>
    </header>
    <div class="card-content">
      <p><strong>${actor.name}</strong> gains <strong>${roll.total}</strong> luck!</p>
      <p style="opacity:0.8">Pool: ${oldVal} → ${newVal}</p>
    </div>
  </div>`;

await roll.toMessage({
  speaker,
  flavor: content,
  rollMode: game.settings.get("core", "rollMode"),
});

const speaker = ChatMessage.getSpeaker();
const actor = game.actors.get(speaker.actor);

if (!actor) {
  ui.notifications.warn("Select a token or assign a default character.");
  return;
}

const res = actor.system.resources?.secondary;
if (!res) {
  ui.notifications.error("This actor has no secondary resource slot.");
  return;
}

const current = res.value ?? 0;
if (current <= 0) {
  ui.notifications.warn(`${actor.name} has no luck points to spend.`);
  return;
}

// Prompt for how many points to spend
const formContent = `
  <form>
    <div class="form-group">
      <label>Points to spend (available: <strong>${current}</strong>)</label>
      <input type="number" name="points" value="1" min="1" max="${current}"
             autofocus />
    </div>
  </form>`;

new Dialog({
  title: "Spend Luck",
  content: formContent,
  buttons: {
    spend: {
      icon: '<i class="fas fa-dice-d20"></i>',
      label: "Spend",
      callback: async (html) => {
        const points = Math.clamped(
          parseInt(html.find('[name="points"]').val()) || 0,
          0,
          current
        );
        if (points <= 0) return;

        const newVal = current - points;
        await actor.update({
          "system.resources.secondary.value": newVal,
        });

        await ChatMessage.create({
          speaker,
          content: `
            <div class="dnd5e chat-card">
              <header class="card-header flexrow">
                <img src="icons/svg/d20-grey.svg" width="36" height="36"/>
                <h3>Luck Spent</h3>
              </header>
              <div class="card-content">
                <p><strong>${actor.name}</strong> spends
                   <strong>${points}</strong> luck point${points > 1 ? "s" : ""}
                   (+${points} to a roll).</p>
                <p style="opacity:0.8">Pool: ${current} → ${newVal}</p>
              </div>
            </div>`,
          rollMode: game.settings.get("core", "rollMode"),
        });
      },
    },
    cancel: {
      icon: '<i class="fas fa-times"></i>',
      label: "Cancel",
    },
  },
  default: "spend",
}).render(true);

const SYNC_URL =
  "https://raw.githubusercontent.com/DoomedBastion79/Shogun/main/sync-payload.json";
const MODULE_ID = "kagekuni-assistant";

if (!game.user.isGM) {
  ui.notifications.warn("Only the GM can run Kagekuni Sync.");
  return;
}

ui.notifications.info("Kagekuni Sync: Fetching latest payload...");
let payload;
try {
  const resp = await fetch(SYNC_URL);
  if (!resp.ok) throw new Error(`HTTP ${resp.status}: ${resp.statusText}`);
  payload = await resp.json();
} catch (err) {
  ui.notifications.error(`Sync failed: could not fetch payload. ${err.message}`);
  console.error("Kagekuni Sync fetch error:", err);
  return;
}

console.log(
  `Kagekuni Sync: payload v${payload.version} (${payload.generated})`
);

const results = [];
const packEntries = Object.entries(payload.packs || {});

for (const [packName, docs] of packEntries) {
  const packId = `${MODULE_ID}.${packName}`;
  const pack = game.packs.get(packId);
  if (!pack) {
    console.warn(`Kagekuni Sync: pack "${packId}" not found, skipping`);
    results.push({ pack: packName, status: "not found" });
    continue;
  }

  try {
    const wasLocked = pack.locked;
    if (wasLocked) await pack.configure({ locked: false });

    // Folder YAML entries carry `color` + `sorting`; split them out so we
    // recreate folders first, then documents that reference them.
    const folders = docs.filter((d) => "color" in d && "sorting" in d);
    const documents = docs.filter((d) => !("color" in d && "sorting" in d));

    const existingFolders = pack.folders.map((f) => f.id);
    if (existingFolders.length > 0) {
      await Folder.deleteDocuments(existingFolders, { pack: packId });
    }

    const existingDocs = pack.index.map((idx) => idx._id);
    const deleted = existingDocs.length + existingFolders.length;
    if (existingDocs.length > 0) {
      const cls = pack.documentClass;
      await cls.deleteDocuments(existingDocs, { pack: packId });
    }

    let created = 0;
    if (folders.length > 0) {
      await Folder.createDocuments(folders, {
        pack: packId,
        keepId: true,
      });
      created += folders.length;
    }

    if (documents.length > 0) {
      const cls = pack.documentClass;
      for (let i = 0; i < documents.length; i += 50) {
        const batch = documents.slice(i, i + 50);
        await cls.createDocuments(batch, {
          pack: packId,
          keepId: true,
          keepEmbeddedIds: true,
        });
        created += batch.length;
      }
    }

    if (wasLocked) await pack.configure({ locked: true });

    results.push({ pack: packName, deleted, created, status: "ok" });
    console.log(
      `Kagekuni Sync: ${packName} — deleted ${deleted}, created ${created}`
    );
  } catch (err) {
    results.push({ pack: packName, status: `error: ${err.message}` });
    console.error(`Kagekuni Sync: ${packName} failed:`, err);
  }
}

const totalCreated = results.reduce((s, r) => s + (r.created || 0), 0);
const totalDeleted = results.reduce((s, r) => s + (r.deleted || 0), 0);
const errors = results.filter((r) => r.status !== "ok" && r.status !== "not found");

const rows = results
  .map((r) => {
    const icon = r.status === "ok" ? "✅" : r.status === "not found" ? "⚠️" : "❌";
    return `<tr>
      <td>${icon}</td>
      <td>${r.pack}</td>
      <td>${r.deleted ?? "-"}</td>
      <td>${r.created ?? "-"}</td>
    </tr>`;
  })
  .join("");

const html = `
  <h3>Kagekuni Sync Complete — v${payload.version}</h3>
  <table style="width:100%; font-size:12px; border-collapse:collapse;">
    <thead>
      <tr style="border-bottom:1px solid #999;">
        <th></th>
        <th style="text-align:left;">Pack</th>
        <th style="text-align:left;">Del</th>
        <th style="text-align:left;">Add</th>
      </tr>
    </thead>
    <tbody>${rows}</tbody>
  </table>
  <p style="font-size:11px; margin-top:8px;">
    ${totalDeleted} removed, ${totalCreated} created.
    ${errors.length ? `<strong>${errors.length} error(s)</strong>` : "No errors."}
  </p>
`;

ChatMessage.create({ content: html, whisper: [game.user.id] });
ui.notifications.info(
  `Kagekuni Sync: ${totalCreated} documents synced across ${results.filter((r) => r.status === "ok").length} packs.`
);
